from typing import Protocol

class ServiceError(Exception):
    """Structured error a service returns; raised by the transport."""
    def __init__(self, code: int, message: str):
        self.code = code
        self.message = message
        super().__init__(f"service error {code}: {message}")

class AsyncTransport(Protocol):
    """Caller-supplied byte carrier. It performs the call named by
    (service, method) — the verbatim CSIL service and operation names, ready
    to go on the wire unmodified — with the already-encoded request bytes and
    returns the response bytes, or raises ServiceError. The generated client
    owns (de)serialization; the carrier only moves bytes.
    """
    async def call(self, service: str, method: str, req: bytes) -> bytes: ...

class IdentityAsyncClient:
    """Typed client for the IdentityService service."""
    def __init__(self, transport: AsyncTransport):
        self._transport = transport

    async def begin_login(self, req: BeginLoginRequest) -> BeginLoginResponse:
        """begin-login"""
        return BeginLoginResponse.from_cbor(await self._transport.call("IdentityService", "begin-login", req.to_cbor()))

    async def poll_login(self, req: PollLoginRequest) -> PollLoginResponse:
        """poll-login"""
        return PollLoginResponse.from_cbor(await self._transport.call("IdentityService", "poll-login", req.to_cbor()))

    async def who_am_i(self, req: WhoAmIRequest) -> WhoAmIResponse:
        """who-am-i"""
        return WhoAmIResponse.from_cbor(await self._transport.call("IdentityService", "who-am-i", req.to_cbor()))

    async def issue_service_token(self, req: IssueServiceTokenRequest) -> TokenResponse:
        """issue-service-token"""
        return TokenResponse.from_cbor(await self._transport.call("IdentityService", "issue-service-token", req.to_cbor()))

    async def refresh(self, req: RefreshRequest) -> TokenResponse:
        """refresh"""
        return TokenResponse.from_cbor(await self._transport.call("IdentityService", "refresh", req.to_cbor()))

